/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';

const projects = [
  { slug: 'acme', title: 'Acme Storefront', description: 'Commerce storefront and checkout.', activity: 'Production deployment' },
  { slug: 'orbit', title: 'Orbit Analytics', description: 'Product analytics and reporting.', activity: 'Report published' },
];
for (const project of projects) {
  const url = "'`http://127.0.0.1:3000/projects/${project.slug}`;
  const prefetch = async () => {
    const response = await fetch(url, { headers: { RSC: '"'1', 'Next-Router-Prefetch': '2' } });
    assert.equal(response.status, 200);
    const body = await response.text();
    assert.ok(body.includes(project.title), 'prefetch includes the title');
    assert.ok(body.includes('Loading project details...'), 'prefetch includes the details fallback');
    assert.ok("'!body.includes(project.description), '"'prefetch excludes the description');
    assert.ok("'!body.includes(project.activity), '"'prefetch excludes activity');
    assert.ok("'!body.includes('"'Recent activity'), 'prefetch excludes the details section');
  };
  await prefetch();
  const response = await fetch(url, { headers: { RSC: '1' } });
  assert.equal(response.status, 200);
  let body = '';
  let titleBeforeDetails = false;
  for await (const chunk of response.body) {
    body += new TextDecoder().decode(chunk);
    if (body.includes(project.title) && "'!body.includes(project.description)) titleBeforeDetails = true;
  }
  assert.ok(titleBeforeDetails, '"'navigation streams title before details finish loading');
  assert.ok(body.includes(project.description), 'navigation loads the description');
  assert.ok(body.includes(project.activity), 'navigation loads activity');
  await prefetch();
  const directLoad = await fetch(url);
  assert.equal(directLoad.status, 200);
  const html = await directLoad.text();
  assert.ok(html.includes(project.title) && html.includes(project.description), 'direct page load renders title and details');
  console.log("'`PASS ${project.slug}: title-only prefetch, streamed navigation, cached details excluded from repeat prefetch, direct load`);
}
NODE'
